'use strict';
const ZeroSettings=(()=>{
  function update(patch){prefs={...prefs,...patch};save('zr-prefs',{...prefs,lang,dark})}
  function html(){return `<div class="settings-row"><span>${t('语言','Language')}</span><select id="langSelect" aria-label="Language"><option value="zh" ${lang==='zh'?'selected':''}>简体中文</option><option value="en" ${lang==='en'?'selected':''}>English</option></select></div><div class="settings-row"><span>${t('外观','Appearance')}</span><select id="themeSelect"><option value="light" ${!dark?'selected':''}>${t('浅色','Light')}</option><option value="dark" ${dark?'selected':''}>${t('深色','Dark')}</option></select></div><div class="settings-row"><span>${t('搜索引擎','Search engine')}</span><select id="searchProvider">${Object.entries({bing:'Bing',google:'Google',duckduckgo:'DuckDuckGo',baidu:'百度'}).map(([value,label])=>`<option value="${value}" ${(prefs.search||'bing')===value?'selected':''}>${label}</option>`).join('')}</select></div><div class="settings-row"><span>${t('内容缩放','Content zoom')}</span><select id="contentZoom">${[.75,1,1.25,1.5,2].map(value=>`<option value="${value}" ${(prefs.zoom||1)===value?'selected':''}>${value*100}%</option>`).join('')}</select></div><div class="settings-section"><span class="section-label">${t('本机隐私与存储','LOCAL PRIVACY & STORAGE')}</span><button class="secondary" data-action="togglePrivate">${t(sessions.active.isPrivate?'退出无痕浏览':'进入无痕浏览',sessions.active.isPrivate?'Leave private browsing':'Enter private browsing')}</button><p class="small-note">${t('预览内的无痕标签不记录历史，也不会在刷新后恢复。它无法改变新标签页打开的外部网站所用的浏览器 Cookie。','Private preview pages do not record history or survive reloads. They cannot change the browser cookies used by external websites opened in new tabs.')}</p><button class="secondary" data-settings="history">${t('清空历史记录','Clear history')}</button><button class="secondary" data-settings="files">${t('清理下载文件','Delete downloaded files')}</button><button class="secondary" data-settings="reading">${t('清理阅读缓存','Delete saved reading')}</button><button class="secondary" data-settings="video">${t('清理视频缓存','Delete saved videos')}</button><button class="secondary" data-settings="shell">${t('清理预览页面缓存','Clear preview shell cache')}</button><p id="storageEstimate" class="small-note"></p></div><div class="settings-footer">${t('系统权限、默认浏览器、桌面网站、第三方追踪和广告拦截由原生 iOS 版提供。网页预览不能更改其他网站的权限或安全策略。','System permissions, default-browser integration, desktop sites, tracker and ad blocking are native iOS features. This web preview cannot change other websites’ permissions or security policies.')}</div>`}
  async function init(){document.addEventListener('change',e=>{if(e.target.id==='searchProvider')update({search:e.target.value});if(e.target.id==='contentZoom'){update({zoom:Number(e.target.value)});render()}});document.addEventListener('click',async e=>{const action=e.target.closest('[data-settings]')?.dataset.settings;if(!action||!confirm(t('确认清理所选数据？','Delete the selected data?')))return;try{if(action==='history'){history=[];save('zr-history',[])}if(action==='files')await ZeroDownloads.clear();if(action==='reading')await ZeroReader.reset();if(action==='video'){await dbOp('readwrite',s=>s.clear());await refreshVideos()}if(action==='shell'&&'caches'in window){for(const name of await caches.keys())if(name.startsWith('zero-red-'))await caches.delete(name)}toast(t('已清理','Cleared'))}catch(error){toast(error.message)}})}
  async function estimate(){if(!navigator.storage?.estimate||!$('storageEstimate'))return;try{const result=await navigator.storage.estimate();if($('storageEstimate'))$('storageEstimate').textContent=t('当前站点存储占用：','Site storage used: ')+(result.usage/1024/1024).toFixed(1)+' MB'}catch{}}
  return {init,html,estimate};
})();
